def is_power_of_prime(N):
    if N <= 1:
        return None, 0
    for p in range(2, int(N**0.5) + 2):
        if N % p == 0:
            count = 0
            temp = N
            while temp % p == 0:
                temp //= p
                count += 1
            if temp == 1:
                return p, count
            else:
                # N has other factors, so it's not a pure prime power
                return None, 0
    # If loop finishes, N is prime itself
    return N, 1

def solve_small_case(M_max, N_max):
    solutions = []
    print(f"Searching for solutions with M <= {M_max} and N <= {N_max}...")
    for m in range(1, M_max + 1):
        for n in range(1, N_max + 1):
            X = m**2 + n
            Y = m + n**2

            p_X, A = is_power_of_prime(X)
            p_Y, B = is_power_of_prime(Y)

            # Check if both are powers of the same prime p, and A, B >= 2
            if p_X is not None and p_Y is not None and p_X == p_Y:
                p = p_X
                if A >= 2 and B >= 2:
                    solutions.append((m, n, p))
                    print(f"Found solution: ({m}, {n}, {p}) where m^2+n = {X} = p^{A} and m+n^2 = {Y} = p^{B}")
    return solutions

# Set a reasonably small limit for the initial search
M_LIMIT = 10
N_LIMIT = 10
solutions = solve_small_case(M_LIMIT, N_LIMIT)
print("\n--- Final List of Candidates ---")
print(solutions)
